## --- Test integrated age program for ZirconHe
    dm = ZRDAAM(
        Ea_z = 165.0,       # kJ/mol
        D0_z = 193188.0,    # cm^2/sec
        Ea_N17 = 71.0,      # kJ/mol
        D0_N17 = 3.4E-3,    # 6.367e-3 cm^2/sec
        rmin=0.0,           # unitless
    )
    pr = Thermochron.anneal(tsteps, Tsteps, dm)
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    for _ in 1:4 # Re-run to ensure internal state does not change
        @test modelage(zircon,Tsteps,dm) ≈ 382.1963474416354
    end

    crystalradius = 35.
    U = 1107.
    Th = 351.
    zircon = ZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps), volumeweighting=:spherical)
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    for _ in 1:4 # Re-run to ensure internal state does not change
        @test modelage(zircon,Tsteps,dm) ≈ 226.89448084711083
    end

    crystalradius = 135.
    U = 1738.
    Th = 1171.
    zircon = ZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps), volumeweighting=:spherical)
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    for _ in 1:4 # Re-run to ensure internal state does not change
        @test modelage(zircon,Tsteps,dm) ≈ 9.775337344388994
    end

    crystalradius = 135.
    U = 500.
    Th = 400.
    zircon = ZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps), volumeweighting=:spherical)
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    for _ in 1:4 # Re-run to ensure internal state does not change
        @test modelage(zircon,Tsteps,dm) ≈ 690.9382149835632
    end

## --- Test integrated age program 10 Ma timestep

    tCryst = 3000.0 # Time (in Myr)
    TCryst = 600 # C
    dt = 10 # time step size in Myr
    dr = 1
    tsteps = (0+dt/2 : dt : tCryst-dt/2)

    # Generate T path to test
    Tr = 150
    T0 = 30
    agePoints = Float64[tCryst, tCryst*29/30,   720, 580, 250,  0] # Age (Ma)
    TPoints  =  Float64[TCryst,        Tr+T0, Tr+T0,  T0,  70, 10] # Temp. (C)
    Tsteps = linterp1s(agePoints,TPoints,reverse(tsteps))

    pr = Thermochron.anneal(tsteps, Tsteps, ZRDAAM(rmin=0.0))
    @test size(pr) == (300,300)
    @test mean(pr) ≈ 0.38342687162656836

    dm = ZRDAAM(
        Ea_z = 165.0, # kJ/mol
        D0_z = 193188.0, # cm^2/sec
        Ea_N17 = 71.0, # kJ/mol
        D0_N17 = 0.0034, #6.367E-3 # cm^2/sec
        rmin=0.0,
    )

    crystalradius = 59.3
    U = 462.98
    Th = 177.76
    zircon = ZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps), volumeweighting=:spherical)
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    @test modelage(zircon,Tsteps,dm) ≈ 137.19455173287585

    zircon = ZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps))
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    @test modelage(zircon,Tsteps,dm) ≈  152.79491426970284

## --- As above but with Sm as well

    crystalradius = 59.3
    U = 462.98
    Th = 177.76
    Sm = 38.13
    zircon = ZirconHe(age=140, age_sigma=5, r=crystalradius,dr=dr,U238=U,Th232=Th,Sm147=Sm,agesteps=reverse(tsteps), volumeweighting=:spherical)
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    @test zircon.r147Sm ≈ fill(1.56203306122449e17, 59)
    @test modelage(zircon,Tsteps,dm) ≈ 137.03090622750042

## --- Test log likelihood

    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    @test Thermochron.model_ll(zircon,Tsteps,dm) ≈ -2.7046868022366883

## --- Check ZRDAAM effective closure temperatures

    # Standard ZRDAAM annealing model
    dm = ZRDAAM()
    rp = RegionalParameters()

    rate = 0.1 # C/Ma
    agesteps = (400:-1:0.)./rate
    Tsteps = collect(agesteps .* rate)
    # Zircons with varying eU
    zr10 = ZirconHe(;r=60, dr=1, U238=10, Th232=0, agesteps)
    zr100 = ZirconHe(;r=60, dr=1, U238=100, Th232=0, agesteps)
    zr1000 = ZirconHe(;r=60, dr=1, U238=1000, Th232=0, agesteps)
    anneal!(zr10, Tsteps, dm, rp)
    @test modelage(zr10, Tsteps, dm)*rate ≈ 117 atol=1
    anneal!(zr100, Tsteps, dm, rp)
    @test modelage(zr100, Tsteps, dm)*rate ≈ 136 atol=1
    anneal!(zr1000, Tsteps, dm, rp)
    @test modelage(zr1000, Tsteps, dm)*rate ≈ 0.00087 atol=0.01

    rate = 1.0 # C/Ma
    agesteps = (400:-1:0.)./rate
    Tsteps = collect(agesteps .* rate)
    # Zircons with varying eU
    zr10 = ZirconHe(;r=60, dr=1, U238=10, Th232=0, agesteps)
    zr100 = ZirconHe(;r=60, dr=1, U238=100, Th232=0, agesteps)
    zr1000 = ZirconHe(;r=60, dr=1, U238=1000, Th232=0, agesteps)
    anneal!(zr10, Tsteps, dm, rp)
    @test modelage(zr10, Tsteps, dm)*rate ≈ 100 atol=1
    anneal!(zr100, Tsteps, dm, rp)
    @test modelage(zr100, Tsteps, dm)*rate ≈ 127 atol=1
    anneal!(zr1000, Tsteps, dm, rp)
    @test modelage(zr1000, Tsteps, dm)*rate ≈ 150 atol=1

    rate = 10.0 # C/Ma
    agesteps = (400:-1:0.)./rate
    Tsteps = collect(agesteps .* rate)
    # Zircons with varying eU
    zr10 = ZirconHe(;r=60, dr=1, U238=10, Th232=0, agesteps)
    zr100 = ZirconHe(;r=60, dr=1, U238=100, Th232=0, agesteps)
    zr1000 = ZirconHe(;r=60, dr=1, U238=1000, Th232=0, agesteps)
    ap250 = ApatiteHe(;age=75, age_sigma=5, r=60, dr=1, U238=250, Th232=0, agesteps)
    anneal!(zr10, Tsteps, dm, rp)
    @test modelage(zr10, Tsteps, dm)*rate ≈ 89 atol=1
    anneal!(zr100, Tsteps, dm, rp)
    @test modelage(zr100, Tsteps, dm)*rate ≈ 115 atol=1
    anneal!(zr1000, Tsteps, dm, rp)
    @test modelage(zr1000, Tsteps, dm)*rate ≈ 145 atol=1

